<?php require __DIR__.'/config/bootstrap.php';$slug=$_GET['slug']??'';$st=db()->prepare("SELECT * FROM tags WHERE slug=?");$st->execute([$slug]);$tag=$st->fetch();if(!$tag){http_response_code(404);exit('404');}$title=$tag['name'].' · Tags';require __DIR__.'/includes/header.php';$st=db()->prepare("SELECT p.* FROM posts p JOIN post_tags pt ON pt.post_id=p.id WHERE pt.tag_id=? AND p.status='published' ORDER BY p.published_at DESC");$st->execute([$tag['id']]);?><h1>Tag: <?=e($tag['name'])?></h1><div class="grid"><?php foreach($st as $p): ?><article class="card"><div class="pad"><h2><a href="post.php?slug=<?=e($p['slug'])?>"><?=e($p['title'])?></a></h2><p><?=e(excerpt($p['content']))?></p></div></article><?php endforeach;?></div><?php require __DIR__.'/includes/footer.php';?>